describe('Product Detail Navigation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.url().should('include', '/inventory.html');
  });

  it('should navigate to product detail page when clicking first product name', () => {
    cy.get('.inventory_item_name').first().click();
    cy.url().should('include', 'inventory-item.html');
  });

  it('should return to catalogue when clicking back button', () => {
    cy.get('.inventory_item_name').first().click();
    cy.url().should('include', 'inventory-item.html');
    cy.get('[data-test="back-to-products"]').click();
    cy.url().should('include', '/inventory.html');
    cy.get('.title').should('contain', 'Products');
  });

  it('should handle navigation when multiple products exist', () => {
    cy.get('.inventory_item_name').should('have.length.greaterThan', 1);
    cy.get('.inventory_item_name').eq(1).click();
    cy.url().should('include', 'inventory-item.html');
    cy.get('[data-test="back-to-products"]').click();
    cy.url().should('include', '/inventory.html');
    cy.get('.title').should('be.visible').and('contain', 'Products');
  });
});
